import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    points = [(data[1 + 2*i], data[2 + 2*i]) for i in range(n)]

    # adjacency[i] is the set of balls removed when ball i is chosen.
    adjacency = [0] * n
    for i, (x, y) in enumerate(points):
        mask = 0
        for j, (a, b) in enumerate(points):
            if i != j and ((x < a and y < b) or (x > a and y > b)):
                mask |= 1 << j
        adjacency[i] = mask

    full = (1 << n) - 1
    seen = {full}
    stack = [full]
    while stack:
        state = stack.pop()
        for i in range(n):
            bit = 1 << i
            if state & bit:
                # Choosing i keeps itself and every currently incomparable ball.
                nxt = state & (full ^ adjacency[i])
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
    print(len(seen) % 998244353)

solve()

