import sys

def solve():
 data=list(map(int,sys.stdin.buffer.read().split())); n=data[0]; arr=data[1:]
 fac=[]
 for x in arr:
  d={}; z=x; q=2
  while q*q<=z:
   while z%q==0:d[q]=d.get(q,0)+1;z//=q
   q+=1
  if z>1:d[z]=d.get(z,0)+1
  fac.append(d)
 primes=set().union(*(d.keys() for d in fac))
 ans=1
 for p in primes:
  dp={0:1}
  for t,d in enumerate(fac):
   e=d.get(p,0); nd={}
   for h,w in dp.items():
    if e==0:
     nd[h]=w*pow(p,h,MOD)%MOD
     continue
    a=h+e
    nd[a]=(nd.get(a,0)+w*pow(p,a,MOD))%MOD
    if h>=e:
     b=h-e; v=pow(p,b,MOD)
     nd[b]=(nd.get(b,0)+w*v)%MOD
    else:
     nd[0]=(nd.get(0,0)+w*pow(p,(e-h)*(t+1),MOD))%MOD
   dp=nd
  ans=ans*sum(dp.values())%MOD
 print(ans)
solve()

