import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    vals=data[1:]
    m=max(vals)
    spf=list(range(m+1))
    for p in range(2,int(m**0.5)+1):
        if spf[p]==p:
            for x in range(p*p,m+1,p):
                if spf[x]==x:
                    spf[x]=p
    nim=0
    for a in vals:
        cnt=0
        while a>1:
            a//=spf[a]
            cnt+=1
        nim ^= cnt
    print('Anna' if nim else 'Bruno')

if __name__=='__main__':
    main()

