import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,q=data[:2]; p=list(range(n)); sz=[1]*n; lo=list(range(n)); hi=list(range(n)); col=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(x):
        r=x
        while p[r]!=r:r=p[r]
        while p[x]!=x:
            y=p[x];p[x]=r;x=y
        return r
    def merge(a,b):
        a=find(a);b=find(b)
        if a==b:return a
        if sz[a]<sz[b]:a,b=b,a
        p[b]=a;sz[a]+=sz[b];lo[a]=min(lo[a],lo[b]);hi[a]=max(hi[a],hi[b])
        return a
    out=[]; idx=2
    for _ in range(q):
        t=data[idx];idx+=1
        if t==1:
            x,c=data[idx]-1,data[idx+1];idx+=2
            r=find(x); old=col[r]
            if old!=c:
                cnt[old]-=sz[r];cnt[c]+=sz[r];col[r]=c
            if lo[r]>0:
                a=find(lo[r]-1);r=find(r)
                if col[a]==col[r]:r=merge(a,r)
            if hi[r]<n-1:
                b=find(hi[r]+1);r=find(r)
                if col[b]==col[r]:r=merge(r,b)
        else:
            c=data[idx];idx+=1;out.append(str(cnt[c]))
    print('\n'.join(out))

if __name__=='__main__':main()

