import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    pos = 2
    for _ in range(n):
        machines.append(tuple(data[pos:pos + 4]))
        pos += 4

    def minimum_cost(target, a, p, b, q):
        if target == 0:
            return 0

        # For fixed x (number of S machines), the cheapest sufficient
        # number of T machines is ceil((target - a*x) / b).
        # Within each residue class modulo b/gcd(a,b), the resulting cost
        # is linear in x, so its minimum is at an endpoint.
        period = b // math.gcd(a, b)
        last_positive = (target - 1) // a
        best = ((target + a - 1) // a) * p  # only S machines

        for residue in range(min(period, last_positive + 1)):
            max_step = (last_positive - residue) // period
            for step in (0, max_step):
                x = residue + step * period
                y = (target - a * x + b - 1) // b
                cost = x * p + y * q
                if cost < best:
                    best = cost
        return best

    def feasible(target):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(target, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        # Stirling numbers of the second kind, one row at a time.
        s = [0] * (n + 1)
        s[0] = 1
        for i in range(1, n + 1):
            for k in range(i, 0, -1):
                s[k] = (s[k - 1] + k * s[k]) % MOD
            s[0] = 0
        ans = 0
        falling = 1
        for k in range(1, min(n, x) + 1):
            falling = falling * (x - k + 1) % MOD
            ans = (ans + falling * s[k] * pow(y, k, MOD)) % MOD
        return ans

