class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        # steps[x] is number of popcount operations to reach 1
        steps = [0] * (m + 1)
        for x in range(2, m + 1):
            steps[x] = 1 + steps[x.bit_count()]
        valid = [t for t in range(1, m + 1) if steps[t] <= k - 1]
        comb = [[0] * (m + 1) for _ in range(m + 1)]
        for a in range(m + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD
        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = m - i - 1
                for t in valid:
                    need = t - prefix_ones
                    if 0 <= need <= remaining:
                        ans += comb[remaining][need]
                prefix_ones += 1
        return ans % MOD

