import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    it=iter(data)
    h=next(it); w=next(it); x=next(it)
    p=next(it)-1; q=next(it)-1
    a=[next(it) for _ in range(h*w)]
    start=p*w+q
    power=a[start]
    seen=bytearray(h*w)
    seen[start]=1
    heap=[]
    def add(u):
        if not seen[u]:
            seen[u]=1
            heapq.heappush(heap,(a[u],u))
    if p: add(start-w)
    if p+1<h: add(start+w)
    if q: add(start-1)
    if q+1<w: add(start+1)
    while heap:
        s,u=heapq.heappop(heap)
        if s*x >= power:
            break
        power+=s
        r,c=divmod(u,w)
        if r: add(u-w)
        if r+1<h: add(u+w)
        if c: add(u-1)
        if c+1<w: add(u+1)
    print(power)
main()

