A=list(map(int,sys.stdin.readline().split()))
K=62
vals=[(-a)%(1<<K) for a in A]
def dfs(arr,b):
    if b==K:
        return len(arr)
    z=[]
    o=[]
    mask=1<<b
    for x in arr:
        if x&mask:
            o.append(x)
        else:
            z.append(x)
    # Choose bit 0 or 1 for i. Keys in the other group terminate here.
    score0=(len(o) if b%2==0 else 0)+(dfs(z,b+1) if z else 0)
    score1=(len(z) if b%2==0 else 0)+(dfs(o,b+1) if o else 0)
    return max(score0,score1)
