from typing import List
import sys
sys.setrecursionlimit(1000000)

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dr = (1, 1, -1, -1)
        dc = (1, -1, -1, 1)  # clockwise order
        size = n * m
        memo = [[-1] * size for _ in range(8)]

        def f(r, c, d, used):
            idx = r * m + c
            state = d * 2 + used
            cached = memo[state][idx]
            if cached != -1:
                return cached

            need = 0 if grid[r][c] == 2 else 2
            best = 1
            nd = d
            nr, nc = r + dr[nd], c + dc[nd]
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == need:
                best = 1 + f(nr, nc, nd, used)

            if not used:
                nd = (d + 1) % 4
                nr, nc = r + dr[nd], c + dc[nd]
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == need:
                    best = max(best, 1 + f(nr, nc, nd, 1))

            memo[state][idx] = best
            return best

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d in range(4):
                        nr, nc = r + dr[d], c + dc[d]
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            ans = max(ans, 1 + f(nr, nc, d, 0))
        return ans

