class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0])
        # clockwise directions in screen coordinates
        dr=(1,1,-1,-1); dc=(1,-1,-1,1)
        @lru_cache(None)
        def f(r,c,d,used):
            v=grid[r][c]
            need=0 if v==2 else 2
            best=1
            choices=[d] if used else [d,(d+1)%4]
            for nd in choices:
                nr,nc=r+dr[nd],c+dc[nd]
                if 0<=nr<n and 0<=nc<m and grid[nr][nc]==need:
                    best=max(best,1+f(nr,nc,nd,used or nd!=d))
