from typing import List
import math
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        ans = []
        prev = None
        while len(ans) < n:
            chosen = None
            for x in sorted(odds + evens):
                if prev is not None and x % 2 == prev % 2:
                    continue
                ro = len(odds) - (x % 2 == 1)
                re = len(evens) - (x % 2 == 0)
                nextpar = 1 - (x % 2)
                m = ro + re
                need_next = (m + 1) // 2
                need_other = m // 2
                if nextpar == 1:
                    valid = ro == need_next and re == need_other
                else:
                    valid = re == need_next and ro == need_other
                cnt = math.factorial(ro) * math.factorial(re) if valid else 0
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            if chosen % 2:
                odds.remove(chosen)
            else:
                evens.remove(chosen)
            prev = chosen
        return ans

