class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = [0] * m
        pows = [1] * n
        for i in range(1, n):
            pows[i] = pows[i - 1] * 10 % k
        for i in range(m):
            coeff[i] = (pows[n - 1 - i] + (pows[i] if i != n - 1 - i else 0)) % k
        dp = [bytearray(k) for _ in range(m + 1)]
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt = dp[i + 1]
            cur = dp[i]
            for d in range(10):
                shift = c * d % k
                for r in range(k):
                    if nxt[r]:
                        cur[(r + shift) % k] = 1
        digits = []
        residue = 0
        for i, c in enumerate(coeff):
            for d in range(9, -1, -1):
                if i == 0 and d == 0:
                    continue
                need = (-residue - c * d) % k
                if dp[i + 1][need]:
                    digits.append(str(d))
                    residue = (residue + c * d) % k
                    break
        half = ''.join(digits)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

