class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        parent[0] = 0
        for u in order:
            for v, _ in graph[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        dp_no_parent = [0] * n
        dp_parent = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp_no_parent[v]
                    gains.append(w + dp_parent[v] - dp_no_parent[v])
            gains.sort(reverse=True)
            best = [0]
            for gain in gains:
                if gain <= 0:
                    break
                best.append(best[-1] + gain)
            dp_no_parent[u] = base + best[min(k, len(best) - 1)]
            dp_parent[u] = base + best[min(k - 1, len(best) - 1)]

        return dp_no_parent[0]

