import sys
from functools import lru_cache

sys.setrecursionlimit(10000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    cards = data[3:]
    allmask = (1 << (n + m + l)) - 1
    t0 = (1 << n) - 1
    a0 = ((1 << m) - 1) << n

    @lru_cache(None)
    def win(t, a, turn):
        hand = t if turn == 0 else a
        if not hand:
            return False
        table = allmask ^ (t | a)
        while hand:
            bit = hand & -hand
            hand -= bit
            x = cards[bit.bit_length() - 1]
            nt = t ^ bit if turn == 0 else t
            na = a ^ bit if turn == 1 else a

            # Put the card on the table without taking another card.
            if turn == 0:
                if not win(nt, a, 1):
                    return True
            else:
                if not win(t, na, 0):
                    return True

            # Or take any smaller-numbered card from the table.
            avail = table
            while avail:
                b = avail & -avail
                avail -= b
                if cards[b.bit_length() - 1] < x:
                    if turn == 0:
                        if not win(nt | b, a, 1):
                            return True
                    else:
                        if not win(t, na | b, 0):
                            return True
        return False

    print('Takahashi' if win(t0, a0, 0) else 'Aoki')

if __name__ == '__main__':
    main()

