import sys, heapq

def solve(data):
 it=iter(map(int,data.split())); n=next(it)
 g=[[] for _ in range(n)]
 for _ in range(n-1):
  u=next(it)-1; v=next(it)-1; w=next(it); g[u].append((v,w)); g[v].append((u,w))
 par=[-1]*n; pw=[0]*n; order=[0]; par[0]=0
 for v in order:
  for u,w in g[v]:
   if u!=par[v]: par[u]=v; pw[u]=w; order.append(u)
 heaps=[None]*n
 for v in reversed(order):
  children=[u for u,w in g[v] if par[u]==v]
  if children:
   big=max(children,key=lambda u:len(heaps[u]))
   h=heaps[big]
  else: h=[]
  for u in children:
   if u==big: continue
   ch=heaps[u]
   first=-heapq.heappop(ch)
   heapq.heappush(h,-(first+pw[u]))
   for x in ch: heapq.heappush(h,x)
   heaps[u]=None
  if children:
   first=-heapq.heappop(h)
   heapq.heappush(h,-(first+pw[big]))
  heapq.heappush(h,0)
  heaps[v]=h
 h=heaps[0]; ans=[]; s=0
 for _ in range(n):
  s-=heapq.heappop(h); ans.append(str(2*s))
 return '\n'.join(ans)

